function maxSumKBlocks(A, k){
  const n=A.length;
  const M=Array.from({length:n},()=>Array(n).fill(0));
  for(let i=0;i<n;i++){ let m=-Infinity; for(let j=i;j>=0;j--){ m=Math.max(m,A[j]); M[j][i]=m; } }
  const dp=Array.from({length:n+1},()=>Array(k+1).fill(-Infinity));
  const split=Array.from({length:n+1},()=>Array(k+1).fill(-1));
  dp[0][0]=0;
  for(let i=1;i<=n;i++){
    for(let t=1;t<=Math.min(k,i);t++){
      for(let j=1;j<=i;j++){
        const val=dp[j-1][t-1]+M[j-1][i-1];
        if(val>dp[i][t]){ dp[i][t]=val; split[i][t]=j; }
      }
    }
  }
  // reconstruction omitted for brevity
  return {best:dp[n][k]};
}
```

